"""
@package mocaxpy.MocaxSpecialPoints
MocaxSpecialPoints module.

Exports the MocaxSpecialPoints class.
"""

import mocaxpy.MocaxCInterface
from mocaxpy.MocaxException import *
import copy
import sys
import ctypes

if sys.version_info.major >= 3:
    long = int
    xrange = range


class MocaxSpecialPoints(object):
    """
    A set of Mocax special points.

    Encapsulates the special points of a Mocax function.
    """

    def __init__(self, points):
        """
        Constructs a complex set of special points (zero or more points per dimension) from a bidimensional container.

        @param[in] points The set of special points.
                          A container of at least one container of coordinates in the domain for each dimension.
                          Allowed types: @c list, @c tuple; contents allowed types: @c int, @c long, @c float, @c list, @c tuple
        """

        # Validation
        if not isinstance(points, (list, tuple)):
            raise TypeError("points has to be a list or a tuple")
        if len(points) < 1:
            raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_DIMENSIONALITY_NOT_ALLOWED, "The special points dimensionality cannot be less than 1."
                                        " len(points) = " + str(len(points)))
        for i in xrange(len(points)):
            if points[i] is None:
                points[i] = []
            if not isinstance(points[i], (list, tuple)):
                points[i] = [points[i]]
            if len(points[i]) < 0:
                raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_NEGATIVE_NUM_SPECIAL_POINTS_PROVIDED,
                                     "The number of special points in a dimension cannot be negative."
                                     "len(points[" + str(i) + "]) = " + str(len(points[i])))
            for j in xrange(len(points[i])):
                if not isinstance(points[i][j], (int, long, float, str)):
                    raise TypeError( "points values must be a real number or a string parseable to a real number. " +
                        type(points[i][j]).__name__ + " was received")
            for j in xrange(len(points[i]) - 1):
                for j2 in range(j + 1, len(points[i])):
                    if points[i][j] == points[i][j2]:
                        raise MocaxException(mocaxpy.MocaxCInterface.MOCAX_E_COINCIDING_SPECIAL_POINTS, "The special points in a dimension cannot overlap. points[" +
                                             str(i) + "][" + str(j) + "] = points[" + str(i) + "][" +
                                             str(j2) + "]; " + str(points[i][j]) + " = " + str(points[i][j2]))

        # Construction
        self.__setup(len(points))
        for i in xrange(len(points)):
            entry = []
            for j in xrange(len(points[i])):
                entry.append(float(points[i][j]))
            entry.sort()
            self.__specialPoints.append(entry)

    def get_num_dimensions(self):
        """
        Gets the number of dimensions of this set of special points.

        @return The number of dimensions of this set.
                Return type: @c int
        """

        return self.__num_dimensions

    def get_num_special_points_for_dimension(self, dimension):
        """
        Gets the number of special points associated to a given dimension.

        @param[in] dimension The index (0-based) of the queried dimension. An integer in the range [0,get_num_dimensions()).
                             Allowed types: @c int, @c long
        @return The number of special points associated to the given dimension.
                Return type: @c int
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parsable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, " +
                             str(self.get_num_dimensions() - 1) + "]")
        return len(self.__specialPoints[dimension])

    def get_point(self, dimension, index):
        """
        Gets one of the special points associated to an specific dimension.

        @param[in] dimension The index (0-based) of the dimension to query.
                             An integer number in the range [0,getNumDimensions()).
                             Allowed types: @c int, @c long
        @param[in] index The index (0-based) of the special point in the given dimension.
                         An integer number in the range [0,getNumSpecialPointsForDimension(dimension)).
                         Allowed tpes: @c int, @c long
        @return The requested special point parameter.
                Return type: @c float
        """

        if not isinstance(dimension, (int, long, str)):
            raise TypeError("dimension has to be an integer or a string parseable as an integer")
        dimension = int(dimension)
        if dimension < 0 or dimension >= self.get_num_dimensions():
            raise IndexError("dimension (" + str(dimension) + ") is out of the range [0, " +
                             str(self.get_num_dimensions() - 1) + "]")
        if not isinstance(index, (int, long, str)):
            raise TypeError("index has to be an integer or a string parseable as an integer")
        index = int(index)
        if index < 0 or index >= self.get_num_special_points_for_dimension(dimension):
            raise IndexError("index (" + str(index) + ") is out of the range [0, " +
                             str(self.get_num_special_points_for_dimension(dimension) - 1) + "]")
        return self.__specialPoints[dimension][index]

    def export_as_multidimensional_array(self):
        """
        Exports the set as a bidimensional C array.

        @note This method is meant to be used internally. For a Python-friendly approach, use export_as_list() instead.

        @return A C-friendly structure containing the special points.
                Return type: <tt>ctypes.POINTER(ctypes.c_double)</tt>
        """

        val = (ctypes.POINTER(ctypes.c_double) * len(self.__specialPoints))()
        for i, v in enumerate(self.__specialPoints):
            val[i] = (ctypes.c_double * len(v))(*v)
        return val

    def export_as_list(self):
        """
        Exports the special points as a native Python list.

        @return A list containing every special point.
                Return type: @c list
        """

        return copy.deepcopy(self.__specialPoints)

    def __str__(self):
        """
        Gets a string representation of this set of special points.
        @return The special points in string format.
                Return type: @c str
        """
        return str(self.export_as_list())

    def __init(self):
        self.__num_dimensions = 0
        self.__specialPoints = []

    def __setup(self, num_dimensions):
        self.__init()
        self.__num_dimensions = num_dimensions
